#include <iostream>
#include <vector>
#include <map>
#include <cstdint>
#include <cassert>
using namespace std;

const int MOD = 1000000007;

struct mod_int {
    int val;

    mod_int(long long v = 0) {
        v %= MOD;
        if (v < 0) v += MOD;
        val = static_cast<int>(v);
    }

    static int mod_inv(int a, int m = MOD) {
        int g = m, r = a, x = 0, y = 1;
        while (r != 0) {
            int q = g / r;
            g %= r; swap(g, r);
            x -= q * y; swap(x, y);
        }
        return x < 0 ? x + m : x;
    }

    explicit operator int() const { return val; }

    mod_int& operator+=(const mod_int &other) {
        val += other.val;
        if (val >= MOD) val -= MOD;
        return *this;
    }

    mod_int& operator-=(const mod_int &other) {
        val -= other.val;
        if (val < 0) val += MOD;
        return *this;
    }

    static unsigned fast_mod(uint64_t x, unsigned m = MOD) {
        return x % m;
    }

    mod_int& operator*=(const mod_int &other) {
        val = fast_mod(static_cast<uint64_t>(val) * other.val);
        return *this;
    }

    mod_int& operator/=(const mod_int &other) {
        return *this *= other.inv();
    }

    friend mod_int operator+(const mod_int &a, const mod_int &b) { return mod_int(a) += b; }
    friend mod_int operator-(const mod_int &a, const mod_int &b) { return mod_int(a) -= b; }
    friend mod_int operator*(const mod_int &a, const mod_int &b) { return mod_int(a) *= b; }
    friend mod_int operator/(const mod_int &a, const mod_int &b) { return mod_int(a) /= b; }

    mod_int& operator++() {
        val = (val == MOD - 1) ? 0 : val + 1;
        return *this;
    }

    mod_int& operator--() {
        val = (val == 0) ? MOD - 1 : val - 1;
        return *this;
    }

    mod_int operator++(int) { mod_int before = *this; ++*this; return before; }
    mod_int operator--(int) { mod_int before = *this; --*this; return before; }

    mod_int operator-() const { return val == 0 ? 0 : MOD - val; }

    bool operator==(const mod_int &other) const { return val == other.val; }
    bool operator!=(const mod_int &other) const { return val != other.val; }

    mod_int inv() const { return mod_inv(val); }

    mod_int pow(long long p) const {
        mod_int a = *this, result = 1;
        while (p > 0) {
            if (p & 1) result *= a;
            a *= a;
            p >>= 1;
        }
        return result;
    }
};

const int N_MAX = 7;
int N;
mod_int probability[N_MAX][N_MAX];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;

    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++) {
            int p;
            cin >> p;
            probability[i][j] = mod_int(p) / mod_int(100);
        }

    map<vector<bool>, mod_int> possible_masks;
    vector<bool> starting(1 << N, false);
    starting[0] = true;
    possible_masks[starting] = mod_int(1);

    for (int left = 0; left < N; left++) {
        map<vector<bool>, mod_int> new_possible_masks;

        for (int current = 0; current < (1 << N); current++) {
            mod_int product = mod_int(1);
            for (int right = 0; right < N; right++) {
                int bit = (current >> right) & 1;
                if (bit) product *= probability[left][right];
                else product *= (mod_int(1) - probability[left][right]);
            }

            for (auto &p : possible_masks) {
                const vector<bool> &possible = p.first;
                mod_int prob = p.second;
                vector<bool> new_possible(1 << N, false);

                for (int mask = 0; mask < (1 << N); mask++) {
                    if (possible[mask]) {
                        for (int i = 0; i < N; i++) {
                            int cur_bit = (current >> i) & 1;
                            int mask_bit = (mask >> i) & 1;
                            if (cur_bit && !mask_bit) {
                                new_possible[mask | (1 << i)] = true;
                            }
                        }
                    }
                }

                new_possible_masks[new_possible] += prob * product;
            }
        }

        possible_masks = move(new_possible_masks);
    }

    mod_int answer = mod_int(0);
    vector<bool> full_mask(1 << N, false);
    full_mask[(1 << N) - 1] = true;

    for (auto &p : possible_masks)
        if (p.first == full_mask)
            answer += p.second;

    cout << (int)answer << '\n';
    return 0;
}
